function translateText(value, language) {
  if (language !== "hi" || typeof value !== "string" || !/[A-Za-z]/.test(value)) return value;
  const normalized = value.trim().replace(/\s+/g, " ").toLowerCase();
  if (HI_PHRASES[normalized]) return HI_PHRASES[normalized];
  return value.replace(/[A-Za-z]+(?:[-'][A-Za-z]+)*/g, word => {
    const lower = word.toLowerCase();
    if (HI_WORDS[lower] !== undefined) return HI_WORDS[lower];
    if (/^(API|CSV|GPS|ESP32|FastAPI|ID|pH|°C)$/i.test(word)) return word.toUpperCase() === "PH" ? "पीएच" : word;
    return word;
  }).replace(/\s{2,}/g, " ").replace(/\s+([.,:;!?])/g, "$1");
}
function translateNode(node, language) {
  if (language !== "hi" || node == null || typeof node === "boolean" || typeof node === "number") return node;
  if (typeof node === "string") return translateText(node, language);
  if (Array.isArray(node)) return node.map((child, i) => <Fragment key={i}>{translateNode(child, language)}</Fragment>);
  if (!isValidElement(node)) return node;
  const props = {};
  for (const [key, value] of Object.entries(node.props || {})) {
    if (key === "children") props.children = translateNode(value, language);
    else if (["placeholder", "title", "aria-label", "alt", "label", "eyebrow", "subtitle", "detail", "unit"].includes(key) && typeof value === "string") props[key] = translateText(value, language);
    else if (key === "value" && node.type?.name === "InfoCell" && typeof value === "string") props[key] = translateText(value, language);
    else props[key] = value;
  }
  // Keep the original option value for form logic while translating its visible label.
  if (node.type === "option" && props.value === undefined) {
    const original = node.props?.children;
    if (typeof original === "string" || typeof original === "number") props.value = String(original);
  }
  return cloneElement(node, props);
}

